package org.sleepwell.app;
import android.app.*;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.function.Consumer;
/** A quantity is a draft until Use quantity; cancelling never edits the record. */
final class TagQuantityDialog extends Dialog {
 final String tag;final EditText amount,unit;
 TagQuantityDialog(Activity a,String tag,TagQuantity current,Bundle state,Consumer<TagQuantity> choose){super(a);this.tag=tag;requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout root=Design.col(a);Design.pad(root,22,22);root.setBackground(Design.shape(a,Design.CREAM,24));Design.text(root,tag+" quantity",21,600,Design.INK);Design.space(root,16);amount=field(a,root,"Tag quantity",state==null?current==null?"":java.math.BigDecimal.valueOf(current.value).stripTrailingZeros().toPlainString():state.getString("amount",""));amount.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);amount.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(30)});unit=field(a,root,"Quantity unit",state==null?current==null?"":current.unit:state.getString("unit",""));unit.setHint("cups, mg, minutes…");unit.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(24)});TextView error=Design.text(root,"",13,500,Design.BROWN);Design.button(root,"Use quantity",true,()->{try{String text=amount.getText().toString().trim();TagQuantity value=new TagQuantity(TagQuantity.parse(text),unit.getText().toString());choose.accept(value);dismiss();}catch(IllegalArgumentException failure){error.setText("Enter a number from 0 to 1,000,000 and a short unit.");}});Design.button(root,"Remove quantity",false,()->{choose.accept(null);dismiss();});Design.button(root,"Cancel",false,this::dismiss);ScrollView scroll=new ScrollView(a);scroll.addView(root);setContentView(scroll);show();getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));getWindow().setLayout(a.getResources().getDisplayMetrics().widthPixels-Design.dp(a,32),-2);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN|WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 static EditText field(Activity a,LinearLayout parent,String label,String text){Design.space(parent,8);Design.text(parent,label,13,500,Design.MUTED);EditText field=new EditText(a);field.setContentDescription(label);field.setSingleLine();field.setText(text);field.setTextSize(18*Appearance.scale(a));field.setTypeface(Design.font(a,400));field.setTextColor(Design.INK);field.setBackground(Design.outline(a,Design.SOFT,Design.LINE,12));Design.pad(field,12,12);parent.addView(field,new LinearLayout.LayoutParams(-1,Design.dp(a,56)));return field;}
 Bundle snapshot(){Bundle state=new Bundle();state.putString("tag",tag);state.putString("amount",amount.getText().toString());state.putString("unit",unit.getText().toString());return state;}
}
